<?php
require_once __DIR__.'/../bootstrap.php';currentUser();$rows=db()->query("SELECT v.id,v.numero_factura,v.fecha,v.cliente_id,v.sucursal_id,CONCAT(c.nombre,' ',c.apellido) cliente,s.nombre sucursal,GROUP_CONCAT(d.descripcion ORDER BY d.id SEPARATOR ', ') detalle,COALESCE(SUM(d.cantidad),1) cantidad,COALESCE(MAX(d.precio_unitario),v.total) precio_unitario,v.total FROM ventas v JOIN clientes c ON c.id=v.cliente_id JOIN sucursales s ON s.id=v.sucursal_id JOIN venta_detalles d ON d.venta_id=v.id GROUP BY v.id ORDER BY v.fecha DESC,v.id DESC")->fetchAll();foreach($rows as &$r){$r['id']=(int)$r['id'];$r['cliente_id']=(int)$r['cliente_id'];$r['sucursal_id']=(int)$r['sucursal_id'];$r['cantidad']=(float)$r['cantidad'];$r['precio_unitario']=(float)$r['precio_unitario'];$r['total']=(float)$r['total'];}respond($rows);
